function Initialize-Directory([string]$path) { if (-not [IO.Directory]::Exists($path)) { [IO.Directory]::CreateDirectory($path) | Out-Null } }
function Get-Hash([string]$path) { if (-not [IO.File]::Exists($path)) { return '' }; return (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Get-Size([string]$path) { if (-not [IO.File]::Exists($path)) { return 0 }; return ([IO.FileInfo]$path).Length }
