function Write-Json([string]$name, $value) { Write-Text $name (($value | ConvertTo-Json -Depth 60) + [Environment]::NewLine) }
function To-BooleanCondition($condition) { if ($condition -is [bool]) { return [bool]$condition };if ($condition -is [string]) { return ([string]$condition -eq 'PASS') };return $false }
function Status($condition) { if (To-BooleanCondition $condition) { return 'PASS' }; return 'BLOCKED' }
function Add-Failure([string]$failureClass, [string]$detail) { [void]$failures.Add([pscustomobject]@{failureClass=$failureClass;detail=$detail;status='ACTIVE'}); if ([string]::IsNullOrWhiteSpace($script:primaryFailure)) { $script:primaryFailure = $failureClass } }
function Add-Gate([string]$name, [string]$status, [string]$detail) { [void]$gates.Add([pscustomobject]@{gate=$name;status=$status;detail=$detail}) }
function Gate($condition, [string]$name, [string]$failureClass, [string]$detail) { $conditionValue=To-BooleanCondition $condition;$gateStatus=Status $conditionValue;Add-Gate $name $gateStatus $detail;if (-not $conditionValue) { Add-Failure $failureClass $detail } }
function Read-Json([string]$path) { return (Get-Content -LiteralPath $path -Raw -Encoding UTF8 | ConvertFrom-Json) }
function Normalize-Manifest($json) { $result=@();if ($json -is [array]) { foreach ($item in @($json)) { $result += [pscustomobject]@{path=[string]$item.path;sha256=[string]$item.sha256} } } elseif ($json.path -is [array]) { $paths=@($json.path);$hashes=@($json.sha256);for ($manifestIndex=0;$manifestIndex -lt $paths.Count;$manifestIndex++) { $result += [pscustomobject]@{path=[string]$paths[$manifestIndex];sha256=[string]$hashes[$manifestIndex]} } } else { $result += [pscustomobject]@{path=[string]$json.path;sha256=[string]$json.sha256} };return $result }
