    try { $resolved=Get-Command $executable -ErrorAction SilentlyContinue;if ($null -eq $resolved) { $missing=$true;$stderr='Executable not found: '+$executable } else { Push-Location $workingDirectory;try { & $executable @commandArgs 1> $stdoutPath 2> $stderrPath;$exitCode=$LASTEXITCODE } finally { Pop-Location };if (Test-Path $stdoutPath) { $stdout=[IO.File]::ReadAllText($stdoutPath) };if (Test-Path $stderrPath) { $stderr=[IO.File]::ReadAllText($stderrPath) } } } catch { $exceptionText=$_.Exception.ToString();$stderr=$exceptionText }
    if (-not (Test-Path $stdoutPath)) { Write-Text $stdoutName $stdout };if (-not (Test-Path $stderrPath)) { Write-Text $stderrName $stderr }
    $successMissing=@($successTokens|Where-Object{ -not [string]::IsNullOrWhiteSpace($_) -and -not $stdout.Contains($_) -and -not $stderr.Contains($_) });$foundFailures=@($failureTokens|Where-Object{ -not [string]::IsNullOrWhiteSpace($_) -and ($stdout.Contains($_) -or $stderr.Contains($_)) });$stderrFailure=($stderr.Length -gt 0 -and -not $allowStderr);$passed=(-not $missing -and [string]::IsNullOrWhiteSpace($exceptionText) -and $exitCode -eq 0 -and $successMissing.Count -eq 0 -and $foundFailures.Count -eq 0 -and -not $stderrFailure);$record=[pscustomobject]@{gate=$gateName;command=($executable+' '+($commandArgs -join ' '));workingDirectory=$workingDirectory;startedUtc=$start;endedUtc=(Get-Date).ToUniversalTime().ToString('o');exitCode=$exitCode;stdoutPath=$stdoutName;stderrPath=$stderrName;stdoutBytes=$stdout.Length;stderrBytes=$stderr.Length;successTokens=$successTokens;missingSuccessTokens=$successMissing;failureTokens=$foundFailures;stderrFailure=$stderrFailure;status=(Status $passed)};[void]$commands.Add($record);return $record
